class Solution {public:vector<vector<int>>solve(vector<int>next){int n=next.size();vector<int>degree(n),length(n),distance(n),order;for(int v:next)degree[v]++;for(int u=0;u<n;u++)if(!degree[u])order.push_back(u);for(int i=0;i<(int)order.size();i++)if(--degree[next[order[i]]]==0)order.push_back(next[order[i]]);for(int u=0;u<n;u++)if(degree[u]&&!length[u]){vector<int>cycle{u};for(int v=next[u];v!=u;v=next[v])cycle.push_back(v);for(int v:cycle)length[v]=cycle.size();}for(int i=order.size()-1;i>=0;i--){int u=order[i];length[u]=length[next[u]];distance[u]=distance[next[u]]+1;}vector<vector<int>>out(n,vector<int>(2));for(int i=0;i<n;i++)out[i]={length[i],distance[i]};return out;}};